                raise ValueError("inspect artifact missing or SHA mismatch")
            with open(path, encoding="utf-8") as fh:
                raw = json.load(fh)
            if not isinstance(raw, list) or len(raw) != 1:
                raise ValueError("inspect must contain exactly one container")
