def row_sha(row):
    return hashlib.sha256(json.dumps(row, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode()).hexdigest()


def import_projection(path, prefix):
    """Remove only bundle duplication from an import copy, never its origin."""
    path = Path(path).resolve()
    origin_sha = sha(path)
    document = json.loads(path.read_text())
    rows = document['handles']
    if not isinstance(rows, list) or document.get('count') != len(rows):
        raise ValueError('import handles count mismatch')
    semantic, ledger = [], []
    for index, original in enumerate(rows):
        if not isinstance(original, dict):
            raise ValueError('import handle must be object')
        projected = {k: v for k, v in original.items() if k not in ('bundle_origin', 'bundle_origins')}
        semantic.append(projected)
        ledger.append({'original_file_sha256': origin_sha, 'original_index': index,
                       'original_row_sha256': row_sha(original), 'semantic_row_sha256': row_sha(projected),
                       'removed_keys': sorted(set(original) - set(projected))})
    projection_path = Path(str(prefix) + '.semantic.json')
    ledger_path = Path(str(prefix) + '.ledger.json')
    if projection_path.exists() or ledger_path.exists():
        raise ValueError('exclusive import derivation required')
    write(projection_path, {'handles': semantic, 'count': len(semantic)})
    proof = {'schema': 'p26-h10-import-projection-v1', 'original_file': str(path),
             'original_file_sha256': origin_sha, 'semantic_file': str(projection_path),
             'semantic_file_sha256': sha(projection_path), 'rows': ledger}
    write(ledger_path, proof)
    return semantic, {'original_file': str(path), 'original_file_sha256': origin_sha,
                      'semantic_file': str(projection_path), 'semantic_file_sha256': sha(projection_path),
                      'ledger_file': str(ledger_path), 'ledger_file_sha256': sha(ledger_path)}


